function sourceField(form,name,label,value,options){options=options||{};var field=el('div','field'+(options.full?' full':'')),caption=el('label','',label),input=el(options.choices?'select':options.multiline?'textarea':'input');input.id=form.id+'-'+name;input.name=name;caption.htmlFor=input.id;if(options.choices){options.choices.forEach(function(choice){var option=el('option','',choice[1]);option.value=choice[0];input.append(option)})}else{if(!options.multiline)input.type='text';if(options.max)input.maxLength=options.max;if(options.placeholder)input.placeholder=options.placeholder;}if(options.required)input.required=true;input.value=value==null?'':String(value);field.append(caption,input);if(options.help){var help=el('small','field-hint',options.help);help.id=input.id+'-help';input.setAttribute('aria-describedby',help.id);field.append(help)}form.append(field);return input}
function displayDate(value){
 if(!value||!/^\d{4}(-\d{2}){0,2}$/.test(value))return value||'';
 if(value.length===4)return value;
 var date=new Date(value+(value.length===7?'-01':'')+'T12:00:00Z');
 if(!Number.isFinite(date.getTime()))return value;
 var options={month:'long',year:'numeric',timeZone:'UTC'};
 if(value.length===10)options.day='numeric';
 return date.toLocaleDateString('fr-FR',options);
}
function sourceDate(event){
 if(event.date_precision==='age')return event.age_text||'Âge non précisé';
 if(event.date_precision==='unknown'||!event.date_start)return 'Sans date';
 return displayDate(event.date_start)+(event.date_end?' – '+displayDate(event.date_end):'');
}
